package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Shape interface {
	Name() string
	Corners() int
	DoubleArea() int64
}

type base struct {
	name    string
	corners int
	d       int64
}

func (b base) Name() string      { return b.name }
func (b base) Corners() int      { return b.corners }
func (b base) DoubleArea() int64 { return b.d }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	var shapes []Shape
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		v := make([]int64, len(f)-1)
		for i := range v {
			v[i], _ = strconv.ParseInt(f[i+1], 10, 64)
		}
		var s base
		switch f[0] {
		case "square":
			s = base{f[0], 4, 2 * v[0] * v[0]}
		case "rect":
			s = base{f[0], 4, 2 * v[0] * v[1]}
		case "rtri":
			s = base{f[0], 3, v[0] * v[1]}
		case "trap":
			s = base{f[0], 4, (v[0] + v[1]) * v[2]}
		default:
			continue
		}
		shapes = append(shapes, s)
	}
	var total int64
	var best Shape
	for _, s := range shapes {
		fmt.Printf("%s corners=%d area2=%d\n", s.Name(), s.Corners(), s.DoubleArea())
		total += s.DoubleArea()
		if best == nil || s.DoubleArea() > best.DoubleArea() {
			best = s
		}
	}
	fmt.Printf("total area2=%d\n", total)
	if best == nil {
		fmt.Println("largest=none")
	} else {
		fmt.Printf("largest=%s area2=%d\n", best.Name(), best.DoubleArea())
	}
}
